<?php
/*
 * Nunca por web. Se comprueba por la peticion, no por el SAPI: en algunos
 * cPanel el `php` de la terminal es un binario CGI, y comparar con 'cli' a
 * secas hacia que el script terminara en silencio, sin imprimir nada.
 */
if ( PHP_SAPI !== 'cli' && ( isset( $_SERVER['REQUEST_METHOD'] ) || isset( $_SERVER['HTTP_HOST'] ) ) ) {
    exit;
}
// Si algo revienta, que se vea aqui y no solo en un log que nadie mira.
@ini_set( 'display_errors', '1' );
@ini_set( 'log_errors', '1' );
error_reporting( E_ALL );
/**
 * HOMVUK - Reserva Directa (hvkp-directa)
 *
 * Instala la pagina de reserva directa que se le manda a los huespedes que
 * llegan por Airbnb, y el generador de enlaces para el anfitrion.
 *
 *   https://homvuk.com/reserva-directa/          (publica, por departamento)
 *   https://homvuk.com/reserva-directa/enlace/   (generador, pide sesion de admin)
 *
 * El huesped ve el mismo departamento y las mismas fechas, con el total sin la
 * comision de servicio del 16% que Airbnb le cobra, y reserva en dos clics
 * usando el checkout que ya existe.
 *
 * Todo vive en la base de datos (Code Snippets), sin archivos nuevos.
 *
 * Uso:  php hvkp-directa.php                              (instalar)
 *       php hvkp-directa.php restore                      (desactivar)
 *       php hvkp-directa.php clave                         (rota la clave del
 *           generador: el enlace anterior deja de servir)
 *       php hvkp-directa.php enlazar <unidad> <producto>   (unir una unidad del
 *           portal con su producto, para que la pagina lea la disponibilidad
 *           real y el huesped reciba su acceso al portal al pagar)
 */

$HVKDB_B64  = '';
$HVKDB_MD5  = '28f81b00e17c55c28e9bfcca42cec0d8';
$HVKDB_NAME = 'HOMVUK Reserva Directa';

printf( "HOMVUK %s · PHP %s (%s) · %s\n", basename( __FILE__ ), PHP_VERSION, PHP_SAPI, date( 'Y-m-d H:i' ) );

/**
 * Encuentra la instalacion de WordPress.
 *
 * Asumir que esta en la misma carpeta que el script fallaba en silencio -el
 * require moria antes de que nada se imprimiera- cuando WordPress no vive en
 * public_html. Se busca hacia arriba y un nivel hacia abajo, y se puede forzar
 * con WP_PATH=/ruta/a/wordpress php <script>.
 */
function hvkp_buscar_wordpress( $desde ) {
    $forzado = getenv( 'WP_PATH' );
    if ( $forzado ) {
        $forzado = rtrim( $forzado, '/' );
        foreach ( array( $forzado . '/wp-load.php', $forzado ) as $c ) {
            if ( is_file( $c ) && 'wp-load.php' === basename( $c ) ) {
                return $c;
            }
        }
        echo "[ERROR] WP_PATH=$forzado no contiene wp-load.php\n";
        exit( 1 );
    }

    $dir = $desde;
    for ( $i = 0; $i < 6; $i++ ) {
        if ( is_file( $dir . '/wp-load.php' ) ) {
            return $dir . '/wp-load.php';
        }
        $padre = dirname( $dir );
        if ( $padre === $dir ) {
            break;
        }
        $dir = $padre;
    }

    // Un nivel hacia abajo. Si aparece mas de una instalacion no se elige por
    // el agente: equivocarse de sitio aqui es escribir en la base que no era.
    foreach ( array( $desde, dirname( $desde ) ) as $base ) {
        $cand = array_values( array_filter( (array) glob( $base . '/*/wp-load.php' ), 'is_file' ) );
        if ( 1 === count( $cand ) ) {
            return $cand[0];
        }
        if ( count( $cand ) > 1 ) {
            echo "[ERROR] Hay varias instalaciones de WordPress cerca:\n";
            foreach ( $cand as $c ) {
                echo '          ' . dirname( $c ) . "\n";
            }
            echo "        Elige una:  WP_PATH=<la que sea> php " . basename( __FILE__ ) . "\n";
            exit( 1 );
        }
    }
    return '';
}

$hvkp_wp = hvkp_buscar_wordpress( __DIR__ );
if ( ! $hvkp_wp ) {
    echo "[ERROR] No encontre WordPress (wp-load.php) desde " . __DIR__ . "\n";
    echo "        Buscalo con:  find ~ -maxdepth 4 -name wp-load.php 2>/dev/null\n";
    echo "        Y luego:      WP_PATH=/la/carpeta/que/salga php " . basename( __FILE__ ) . "\n";
    exit( 1 );
}
if ( dirname( $hvkp_wp ) !== __DIR__ ) {
    echo 'WordPress: ' . dirname( $hvkp_wp ) . "\n";
}
echo "\n";

require $hvkp_wp;

global $wpdb;

$tabla = $wpdb->prefix . 'snippets';
$mode  = isset( $argv[1] ) ? $argv[1] : 'instalar';

/** Vuelve a escribir las reglas de URL con /reserva-directa/ incluida. */
function hvkdb_flush( $con_reglas = true ) {
    if ( $con_reglas ) {
        add_rewrite_rule( '^reserva-directa/enlace/?$', 'index.php?hvkdb=enlace', 'top' );
        add_rewrite_rule( '^reserva-directa/?$', 'index.php?hvkdb=publica', 'top' );
        add_filter( 'query_vars', function ( $v ) { $v[] = 'hvkdb'; return $v; } );
    }
    flush_rewrite_rules( false );
}

if ( 'restore' === $mode ) {
    $wpdb->update( $tabla, array( 'active' => 0 ), array( 'name' => $HVKDB_NAME ) );
    hvkdb_flush( false );
    if ( function_exists( 'wp_cache_flush' ) ) { wp_cache_flush(); }
    do_action( 'litespeed_purge_all' );
    echo "[OK]    Desactivado. /reserva-directa/ deja de responder.\n";
    exit( 0 );
}
if ( 'clave' === $mode ) {
    $nueva = bin2hex( random_bytes( 20 ) );
    update_option( 'hvkdb_clave', $nueva, false );
    echo "[OK]    Clave rotada. El enlace anterior ya no sirve. El nuevo es:\n";
    echo '        ' . home_url( '/reserva-directa/enlace/?k=' . $nueva ) . "\n";
    exit( 0 );
}
if ( 'enlazar' === $mode ) {
    $u_slug = isset( $argv[2] ) ? $argv[2] : '';
    $p_slug = isset( $argv[3] ) ? $argv[3] : '';
    if ( ! $u_slug || ! $p_slug ) {
        echo "[ERROR] Uso: php hvkp-directa.php enlazar <unidad> <producto>\n";
        echo "        Ej.: php hvkp-directa.php enlazar magnolio-306 exclusivo-departamento-en-san-damian-vitacura\n";
        exit( 1 );
    }
    $u = $wpdb->get_row( $wpdb->prepare(
        "SELECT id, name FROM {$wpdb->prefix}portal_units WHERE slug = %s", $u_slug ) );
    if ( ! $u ) {
        echo "[ERROR] No existe la unidad '$u_slug'.\n";
        exit( 1 );
    }
    $p = $wpdb->get_row( $wpdb->prepare(
        "SELECT ID, post_title FROM {$wpdb->posts} WHERE post_name = %s AND post_type = 'product' AND post_status != 'trash' LIMIT 1",
        $p_slug ) );
    if ( ! $p ) {
        echo "[ERROR] No existe el producto '$p_slug'.\n";
        exit( 1 );
    }
    $wpdb->update( $wpdb->prefix . 'portal_units', array( 'listing_id' => (int) $p->ID ), array( 'id' => (int) $u->id ) );
    echo "[OK]    {$u->name} quedo enlazada con \"{$p->post_title}\" (id {$p->ID}).\n";
    exit( 0 );
}
if ( 'instalar' !== $mode ) {
    echo "[ERROR] Argumento no reconocido: $mode. Usa 'instalar', 'restore', 'clave' o 'enlazar'.\n";
    exit( 1 );
}

$code = base64_decode( $HVKDB_B64 );
if ( md5( $code ) !== $HVKDB_MD5 ) {
    echo "[ERROR] El contenido no paso la verificacion. Nada fue modificado.\n";
    exit( 1 );
}
if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $tabla ) ) !== $tabla ) {
    echo "[ERROR] No existe la tabla de snippets (plugin Code Snippets).\n";
    exit( 1 );
}

$ok = array(); $warn = array();

$fila = array(
    'name'        => $HVKDB_NAME,
    'description' => 'Pagina publica de reserva directa (sin la comision de Airbnb) y generador de enlaces.',
    'code'        => $code,
    'tags'        => 'homvuk',
    // Alcance global, no 'front-end': admin-ajax.php cuenta como admin
    // (snippet-ops.php:604 usa is_admin()), y con 'front-end' el snippet no se
    // ejecuta ahi, asi que las acciones wp_ajax_* nunca quedan registradas y
    // WordPress responde un escueto "0". Ademas hace falta en el admin para el
    // menu y para crear la reserva del portal cuando el pedido se completa.
    'scope'       => 'global',
    'priority'    => 10,
    'active'      => 1,
    'modified'    => current_time( 'mysql' ),
);
$existe = $wpdb->get_var( $wpdb->prepare( "SELECT id FROM $tabla WHERE name = %s", $HVKDB_NAME ) );
if ( $existe ) {
    $wpdb->update( $tabla, $fila, array( 'id' => (int) $existe ) );
    $ok[] = "Snippet actualizado (id $existe)";
} else {
    $wpdb->insert( $tabla, $fila );
    $ok[] = 'Snippet instalado (id ' . $wpdb->insert_id . ')';
}

// Las reglas de URL: hay que reescribirlas para que /reserva-directa/ exista.
hvkdb_flush( true );
$ok[] = 'Reglas de URL actualizadas';

// Clave del generador: permite abrirlo desde cualquier navegador, sin sesion.
$clave = (string) get_option( 'hvkdb_clave', '' );
if ( strlen( $clave ) < 20 ) {
    $clave = bin2hex( random_bytes( 20 ) );
    update_option( 'hvkdb_clave', $clave, false );
    $ok[] = 'Clave del generador creada';
}
$url_generador = home_url( '/reserva-directa/enlace/?k=' . $clave );

if ( function_exists( 'wp_cache_flush' ) ) { wp_cache_flush(); }
do_action( 'litespeed_purge_all' );
if ( function_exists( 'rocket_clean_domain' ) ) { rocket_clean_domain(); }
$ok[] = 'Caches purgadas';

/* --- Revision de cada departamento -------------------------------------- */

$tasa = (float) get_option( 'tasaCLP', 0 );
if ( $tasa <= 0 ) { $tasa = 816.0; }

$props = get_posts( array(
    'post_type'      => 'product',
    'post_status'    => 'publish',
    'posts_per_page' => 60,
    'fields'         => 'ids',
    'orderby'        => 'title',
    'order'          => 'ASC',
    'meta_query'     => array( array( 'key' => 'ovabrw_define_1_day', 'value' => 'hotel' ) ),
) );

echo "\n== Departamentos reservables ==\n";
if ( ! $props ) {
    $warn[] = 'No se encontro ningun producto cobrado por noche (ovabrw_define_1_day = hotel).';
} else {
    $in  = gmdate( 'Y-m-d', strtotime( '+14 days' ) );
    $out = gmdate( 'Y-m-d', strtotime( '+21 days' ) );
    foreach ( $props as $pid ) {
        $post  = get_post( $pid );
        $linea = sprintf( '  %-46s id=%-5d', mb_substr( get_the_title( $pid ), 0, 44 ), $pid );
        try {
            $total = get_price_by_date( $pid, strtotime( $in ), strtotime( $out ), array(
                'product_id'            => $pid,
                'ovabrw_number_vehicle' => 1,
                'resources'             => array(),
                'ovabrw_service'        => '[]',
                'period_price'          => '',
                'ova_type_deposit'      => '',
            ) );
            $usd = isset( $total['line_total'] ) ? (float) $total['line_total'] : 0;
            if ( $usd > 0 ) {
                $linea .= sprintf( ' 7 noches = USD %s (~$%s CLP)  OK',
                    number_format( $usd, 2, ',', '.' ),
                    number_format( round( $usd * $tasa ), 0, ',', '.' ) );
            } else {
                $linea .= ' sin tarifa para esas fechas';
                $warn[] = $post->post_name . ': el motor no devuelve tarifa; el enlace tendra que llevar precio fijo.';
            }
        } catch ( \Throwable $e ) {
            $linea .= ' ERROR: ' . $e->getMessage();
            $warn[] = $post->post_name . ': el motor de precios falla (' . $e->getMessage() . ').';
        }
        echo $linea . "\n";
        echo '     ' . home_url( '/reserva-directa/?casa=' . $post->post_name ) . "\n";
    }
}

/* --- Unidades del portal y su producto ----------------------------------- */

$tu = $wpdb->prefix . 'portal_units';
if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $tu ) ) === $tu ) {
    echo "\n== Unidades del portal ==\n";
    $uds = $wpdb->get_results( "SELECT id, name, slug, listing_id FROM $tu WHERE active = 1 ORDER BY name" );
    foreach ( $uds as $u ) {
        if ( $u->listing_id ) {
            $t = get_the_title( (int) $u->listing_id );
            printf( "  %-18s -> %s (id %d)\n", $u->slug, $t ? $t : '(producto inexistente)', $u->listing_id );
        } else {
            printf( "  %-18s -> sin producto enlazado\n", $u->slug );
            $warn[] = $u->slug . ': sin producto enlazado. Sin eso la pagina no lee el calendario de Airbnb '
                . 'ni le crea el acceso al portal al huesped que pague. Enlazalo con: '
                . 'php hvkp-directa.php enlazar ' . $u->slug . ' <slug-del-producto>';
        }
    }
}

/* --- Ultimos errores del servidor, para diagnosticar paginas caidas ------ */

echo "\n== Ultimos errores de PHP ==\n";
$logs = array( ABSPATH . 'error_log', WP_CONTENT_DIR . '/debug.log', ABSPATH . '../logs/error_log' );
$visto = false;
foreach ( $logs as $log ) {
    if ( ! file_exists( $log ) || ! is_readable( $log ) ) { continue; }
    $lineas = @file( $log, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES );
    if ( ! $lineas ) { continue; }
    $fatales = array_values( array_filter( $lineas, function ( $l ) {
        return stripos( $l, 'Fatal error' ) !== false || stripos( $l, 'Uncaught' ) !== false;
    } ) );
    if ( $fatales ) {
        $visto = true;
        echo "  $log\n";
        foreach ( array_slice( $fatales, -5 ) as $f ) {
            echo '    ' . mb_substr( trim( $f ), 0, 190 ) . "\n";
        }
    }
}
if ( ! $visto ) { echo "  (sin errores fatales registrados)\n"; }

/* --- Comprobacion en vivo ------------------------------------------------ */

$res = wp_remote_get( home_url( '/reserva-directa/?v=' . time() ), array( 'timeout' => 45, 'sslverify' => false ) );
if ( is_wp_error( $res ) ) {
    $warn[] = 'No se pudo comprobar la pagina publica: ' . $res->get_error_message();
} else {
    $cod  = (int) wp_remote_retrieve_response_code( $res );
    $body = (string) wp_remote_retrieve_body( $res );
    if ( 200 === $cod && false !== strpos( $body, 'hd-tag' ) ) {
        $ok[] = 'Verificado: la pagina del huesped responde correctamente';
    } else {
        $warn[] = "La pagina del huesped respondio $cod. Si es 404, vuelve a guardar los enlaces permanentes en Ajustes > Enlaces permanentes.";
    }
}

// El generador, abierto con la clave y SIN sesion: es exactamente lo que va a
// hacer el navegador del anfitrion.
$res = wp_remote_get( $url_generador . '&v=' . time(), array( 'timeout' => 45, 'sslverify' => false ) );
if ( is_wp_error( $res ) ) {
    $warn[] = 'No se pudo comprobar el generador: ' . $res->get_error_message();
} else {
    $cod  = (int) wp_remote_retrieve_response_code( $res );
    $body = (string) wp_remote_retrieve_body( $res );
    if ( 200 === $cod && false !== strpos( $body, 'id="gCasa"' ) ) {
        $ok[] = 'Verificado: el generador abre con la clave, sin necesidad de iniciar sesion';
    } else {
        $warn[] = "El generador respondio $cod sin mostrar el formulario. Revisa que el snippet este activo.";
    }
}

// El endpoint de cotizacion: si el alcance del snippet no fuera el correcto,
// admin-ajax.php devolveria "0" y la pagina se quedaria sin cifras.
$prueba = wp_remote_post( admin_url( 'admin-ajax.php' ), array(
    'timeout'   => 45,
    'sslverify' => false,
    'body'      => array(
        'action' => 'hvkdb_cotizar',
        'casa'   => $props ? get_post( $props[0] )->post_name : '',
        'in'     => gmdate( 'Y-m-d', strtotime( '+14 days' ) ),
        'out'    => gmdate( 'Y-m-d', strtotime( '+21 days' ) ),
        'pax'    => 2,
    ),
) );
if ( is_wp_error( $prueba ) ) {
    $warn[] = 'No se pudo comprobar el calculo de precios: ' . $prueba->get_error_message();
} else {
    $cuerpo = trim( (string) wp_remote_retrieve_body( $prueba ) );
    $json   = json_decode( $cuerpo, true );
    if ( is_array( $json ) && ! empty( $json['success'] ) && isset( $json['data']['directo_clp'] ) ) {
        $ok[] = 'Verificado: el calculo de precios responde (' . $json['data']['noches'] . ' noches = '
            . $json['data']['directo_clp'] . ')';
    } elseif ( '0' === $cuerpo ) {
        $warn[] = 'El calculo de precios devuelve "0": el snippet no se esta ejecutando en admin-ajax.php. '
            . 'Revisa que su alcance sea Global en Code Snippets.';
    } else {
        $warn[] = 'El calculo de precios respondio algo inesperado: ' . mb_substr( $cuerpo, 0, 120 );
    }
}

echo "\n== HOMVUK - Reserva Directa ==\n";
foreach ( $ok as $m )   { echo "[OK]    $m\n"; }
foreach ( $warn as $m ) { echo "[AVISO] $m\n"; }
echo "\n== Tu enlace al generador ==\n";
echo "Guardalo en favoritos. Funciona en cualquier navegador, tambien de incognito\n";
echo "y en el telefono, sin iniciar sesion. Es privado: no lo compartas.\n\n";
echo '  ' . $url_generador . "\n";
echo "\nSi alguna vez se te escapa, rotalo con: php hvkp-directa.php clave\n";
echo "Para desactivar todo: php hvkp-directa.php restore\n";
